package com.campus.trade.ai.dispute; import org.springframework.boot.context.properties.ConfigurationProperties; import java.time.Duration; @ConfigurationProperties(prefix="ai.dispute") public class DisputeAgentProperties { private boolean enabled; private String model="deepseek-v4-flash"; private Duration staleAfter=Duration.ofMinutes(10); public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public String getModel(){return model;} public void setModel(String v){model=v;} public Duration getStaleAfter(){return staleAfter;} public void setStaleAfter(Duration v){staleAfter=v;} }
